#include <stdio.h>
#include <string.h>

int main() {
    const char *names[] = {"delta", "alpha", "charlie", "bravo"};
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            if (strcmp(names[i], names[j]) > 0) {
                const char *temp = names[i];
                names[i] = names[j];
                names[j] = temp;
            }
        }
    }
    for (int i = 0; i < 4; i++) {
        printf("%s\n", names[i]);
    }
    return 0;
}
